CREATE TABLE budgets(trip_id VARCHAR2(36) PRIMARY KEY,amount NUMBER(14,2) NOT NULL CHECK(amount>0),currency CHAR(3) NOT NULL,version NUMBER(19) DEFAULT 0 NOT NULL,updated_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL);
CREATE TABLE expenses(id VARCHAR2(36) PRIMARY KEY,trip_id VARCHAR2(36) NOT NULL,actor_id VARCHAR2(36) NOT NULL,description VARCHAR2(200) NOT NULL,amount NUMBER(14,2) NOT NULL CHECK(amount>0),currency CHAR(3) NOT NULL,created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,version NUMBER(19) DEFAULT 0 NOT NULL);
CREATE INDEX expenses_trip ON expenses(trip_id,created_at);
CREATE TABLE expense_splits(expense_id VARCHAR2(36) REFERENCES expenses(id),account_id VARCHAR2(36),amount NUMBER(14,2) NOT NULL CHECK(amount>=0),PRIMARY KEY(expense_id,account_id));
